import { cookies, headers } from 'next/headers';

export default async function Home() {
  const cookieStore = await cookies();
  const headersList = await headers();

  const themeCookie = cookieStore.get('theme');
  const theme = themeCookie?.value || 'light';

  const acceptLanguage = headersList.get('accept-language') || 'Not specified';

  return (
    <main style={{ padding: '2rem' }}>
      <h1>User Preferences</h1>
      <div style={{ marginTop: '1rem' }}>
        <h2>Theme Preference</h2>
        <p>
          <strong>Current theme:</strong> {theme}
        </p>
        {!themeCookie && <p style={{ color: '#666', fontSize: '0.9rem' }}>(Using default theme)</p>}
      </div>
      <div style={{ marginTop: '1.5rem' }}>
        <h2>Language Preference</h2>
        <p>
          <strong>Accept-Language header:</strong> {acceptLanguage}
        </p>
      </div>
    </main>
  );
}

